CREATE TABLE IF NOT EXISTS "TvScreen" ("id" TEXT PRIMARY KEY NOT NULL, "storeId" TEXT NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "config" TEXT NOT NULL DEFAULT '{}', "revision" INTEGER NOT NULL DEFAULT 1, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "TvScreen_storeId_code_key" ON "TvScreen"("storeId", "code");
CREATE INDEX IF NOT EXISTS "TvScreen_storeId_idx" ON "TvScreen"("storeId");
CREATE TABLE IF NOT EXISTS "TvDevice" ("id" TEXT PRIMARY KEY NOT NULL, "storeId" TEXT NOT NULL, "screenId" TEXT NOT NULL REFERENCES "TvScreen"("id") ON DELETE CASCADE, "tokenHash" TEXT NOT NULL UNIQUE, "revoked" BOOLEAN NOT NULL DEFAULT false, "report" TEXT NOT NULL DEFAULT '{}', "lastSeen" TIMESTAMP, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "TvDevice_storeId_screenId_idx" ON "TvDevice"("storeId", "screenId");
CREATE TABLE IF NOT EXISTS "TvPairSession" ("id" TEXT PRIMARY KEY NOT NULL, "pin" TEXT NOT NULL UNIQUE, "secretHash" TEXT NOT NULL, "expiresAt" TIMESTAMP NOT NULL, "claimed" BOOLEAN NOT NULL DEFAULT false, "deviceId" TEXT, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "TvPairSession_expiresAt_idx" ON "TvPairSession"("expiresAt");
